/**
 * Pure helpers for the host <-> Rumbos app postMessage protocol (contract v5, up to v5.8).
 *
 * Nothing here touches the DOM or Moodle APIs, so it can be unit tested with
 * plain Node (see tests/js).
 *
 * @module     format_rumbos/protocol
 * @copyright  2026 OBJ Digital
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

export const PROTOCOL_VERSION = 1;

export const MESSAGE = {
    EMBED_READY: 'rumbos:embed-ready',
    REQUEST_STATE: 'rumbos:request-state',
    REQUEST_LAUNCH: 'rumbos:request-launch',
    OPEN_ACTIVITY: 'rumbos:open-activity',
    OPEN_ACTIVITY_SETTINGS: 'rumbos:open-activity-settings',
    REQUEST_FULLSCREEN: 'rumbos:request-fullscreen',
    REQUEST_STATS: 'rumbos:request-stats',
    REQUEST_FLOW_PROGRESS: 'rumbos:request-flow-progress',
    FLOW_STEP_DONE: 'rumbos:flow-step-done',
    REQUEST_QUIZ_RESULT: 'rumbos:request-quiz-result',
    FLOW_RESET: 'rumbos:flow-reset',
    ERROR: 'rumbos:error',
    NO_CONTENT: 'rumbos:no-content',
    PREFERRED_SIZE: 'rumbos:preferred-size',
    HOST_INIT: 'rumbos:host-init',
    HOST_STATE: 'rumbos:host-state',
    HOST_LAUNCH: 'rumbos:host-launch',
    HOST_FULLSCREEN: 'rumbos:host-fullscreen',
    HOST_STATS: 'rumbos:host-stats',
    HOST_OVERLAY: 'rumbos:host-overlay',
    HOST_FLOW_PROGRESS: 'rumbos:host-flow-progress',
    HOST_QUIZ_RESULT: 'rumbos:host-quiz-result',
};

/**
 * Messages the activity page inside the popup sends to the host (same origin, not part of the app contract).
 */
export const POPUP_MESSAGE = {
    LEAVE: 'rumbos:popup-leave',
    ESCAPE: 'rumbos:popup-escape',
};

/** Error codes the app may report (contract v5.1). */
export const ERROR_CODES = ['launch_failed', 'token_refresh_failed', 'app_crashed', 'protocol_unsupported'];

/** Reasons the app may give for having nothing to show (contract v5.5). */
export const NO_CONTENT_REASONS = ['no_saved_map', 'empty_map'];

/** Errors the host may answer a statistics request with (contract v5.7). */
export const STATS_ERRORS = ['capability', 'unavailable'];

/** How a welcome-flow step may have been completed (contract v5.8). */
export const FLOW_METHODS = ['completed', 'fallback', 'unavailable'];

/** Errors the host may answer a flow progress request with (contract v5.8). */
export const FLOW_ERRORS = ['readonly', 'unavailable'];

/** Errors the host may answer a quiz result request with (contract v5.8). */
export const QUIZ_ERRORS = ['not_found', 'unavailable', 'capability'];

/** A map id is a UUID; the host treats it as opaque text (contract v5.8). */
export const MAP_ID_PATTERN = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/** A step key: letters, digits, "_" and "-", at most 16 (contract v5.8). */
export const STEP_KEY_PATTERN = /^[A-Za-z0-9_-]{1,16}$/;

/** The highest revision of a step the host accepts (contract v5.8). */
export const MAX_REVISION = 1000000;

/** Range of the aspect ratio (width / height) the app may prefer (contract v5.5). */
export const ASPECT_RATIO_RANGE = {min: 0.5, max: 4};

/** Maximum length of the untrusted error detail. */
export const MAX_DETAIL_LENGTH = 200;

/**
 * Whether a value is a plain JSON-like object (not null, array or class instance).
 *
 * @param {*} value
 * @returns {boolean}
 */
const isPlainObject = (value) => Object.prototype.toString.call(value) === '[object Object]';

/**
 * Reduces the untrusted error detail to a short single line of text.
 *
 * It is still untrusted: callers must only ever render it with textContent.
 *
 * @param {*} detail
 * @returns {string} Empty when there is no usable detail.
 */
const cleanDetail = (detail) => {
    if (typeof detail !== 'string') {
        return '';
    }
    // eslint-disable-next-line no-control-regex
    return detail.replace(/[\u0000-\u001f\u007f]+/g, ' ').trim().slice(0, MAX_DETAIL_LENGTH);
};

/**
 * Whether a value is a positive integer course module id.
 *
 * @param {*} cmid
 * @returns {boolean}
 */
const isCmid = (cmid) => Number.isSafeInteger(cmid) && cmid > 0;

/**
 * Whether a value is a group id: zero (everyone) or a positive integer.
 *
 * @param {*} groupId
 * @returns {boolean}
 */
const isGroupId = (groupId) => Number.isSafeInteger(groupId) && groupId >= 0;

/**
 * Whether a value is a map id.
 *
 * @param {*} mapId
 * @returns {boolean}
 */
const isMapId = (mapId) => typeof mapId === 'string' && MAP_ID_PATTERN.test(mapId);

/**
 * Whether a value is a step key.
 *
 * @param {*} stepKey
 * @returns {boolean}
 */
const isStepKey = (stepKey) => typeof stepKey === 'string' && STEP_KEY_PATTERN.test(stepKey);

/**
 * Whether a value is a revision in the accepted range.
 *
 * @param {*} revision
 * @returns {boolean}
 */
const isRevision = (revision) => Number.isSafeInteger(revision) && revision >= 0 && revision <= MAX_REVISION;

/**
 * What to keep of each message type the app may send, or null when its fields are not well formed.
 * Fields the app adds beyond these are dropped.
 */
const APP_MESSAGE_PARSERS = {
    [MESSAGE.EMBED_READY]: (data) => ({type: data.type}),
    [MESSAGE.REQUEST_STATE]: (data) => ({type: data.type}),
    [MESSAGE.REQUEST_LAUNCH]: (data) => ({type: data.type}),
    [MESSAGE.OPEN_ACTIVITY]: (data) => isCmid(data.cmid) ? {type: data.type, cmid: data.cmid} : null,
    [MESSAGE.OPEN_ACTIVITY_SETTINGS]: (data) => isCmid(data.cmid) ? {type: data.type, cmid: data.cmid} : null,
    [MESSAGE.REQUEST_FULLSCREEN]: (data) => typeof data.on === 'boolean' ? {type: data.type, on: data.on} : null,
    [MESSAGE.REQUEST_STATS]: (data) => {
        const groupId = data.groupId ?? 0;
        return data.groupId !== null && isGroupId(groupId) ? {type: data.type, groupId} : null;
    },
    [MESSAGE.REQUEST_FLOW_PROGRESS]: (data) => isMapId(data.mapId) ? {type: data.type, mapId: data.mapId} : null,
    [MESSAGE.FLOW_STEP_DONE]: (data) => isMapId(data.mapId) && isStepKey(data.stepKey) && isRevision(data.revision) &&
        FLOW_METHODS.includes(data.method) ?
        {type: data.type, mapId: data.mapId, stepKey: data.stepKey, revision: data.revision, method: data.method} : null,
    [MESSAGE.REQUEST_QUIZ_RESULT]: (data) => isCmid(data.cmid) ? {type: data.type, cmid: data.cmid} : null,
    [MESSAGE.FLOW_RESET]: (data) => isMapId(data.mapId) ? {type: data.type, mapId: data.mapId} : null,
    [MESSAGE.ERROR]: (data) => ERROR_CODES.includes(data.code)
        ? {type: data.type, code: data.code, detail: cleanDetail(data.detail)}
        : null,
    [MESSAGE.NO_CONTENT]: (data) => NO_CONTENT_REASONS.includes(data.reason) ? {type: data.type, reason: data.reason} : null,
    [MESSAGE.PREFERRED_SIZE]: (data) => Number.isFinite(data.aspectRatio) &&
        data.aspectRatio >= ASPECT_RATIO_RANGE.min && data.aspectRatio <= ASPECT_RATIO_RANGE.max ?
        {type: data.type, aspectRatio: data.aspectRatio} : null,
};

/**
 * Validates a message event coming from the app.
 *
 * The event is accepted only when it comes from the expected origin AND from
 * the iframe's own window, carries protocol version 1, and has a known type
 * with well-formed fields. Anything else is ignored.
 *
 * @param {{origin: string, source: *, data: *}} event The message event.
 * @param {{appOrigin: string, frameWindow: *}} expected Expected sender.
 * @returns {?{type: string}} Clean message (type plus its validated fields), or null.
 */
export const parseAppMessage = (event, {appOrigin, frameWindow}) => {
    if (!event || !frameWindow || event.origin !== appOrigin || event.source !== frameWindow) {
        return null;
    }
    const data = event.data;
    if (!isPlainObject(data) || data.v !== PROTOCOL_VERSION || typeof data.type !== 'string') {
        return null;
    }
    // Own keys only: a type such as "constructor" must not find a parser on the prototype.
    return Object.hasOwn(APP_MESSAGE_PARSERS, data.type) ? APP_MESSAGE_PARSERS[data.type](data) : null;
};

/**
 * The host-init message.
 *
 * @param {{mode: string, locale: string, courseId: number, courseName: string, assertion: string, state: Object}} init
 * @returns {Object}
 */
export const hostInit = ({mode, locale, courseId, courseName, assertion, state}) => ({
    type: MESSAGE.HOST_INIT,
    v: PROTOCOL_VERSION,
    mode,
    locale,
    courseId,
    courseName,
    assertion,
    state,
});

/**
 * The host-state message.
 *
 * @param {Object} state CourseState.
 * @returns {Object}
 */
export const hostState = (state) => ({type: MESSAGE.HOST_STATE, v: PROTOCOL_VERSION, state});

/**
 * The host-launch message.
 *
 * @param {string} assertion Signed launch assertion.
 * @returns {Object}
 */
export const hostLaunch = (assertion) => ({type: MESSAGE.HOST_LAUNCH, v: PROTOCOL_VERSION, assertion});

/**
 * The host-fullscreen message: the host's actual fullscreen state.
 *
 * @param {boolean} on
 * @returns {Object}
 */
export const hostFullscreen = (on) => ({type: MESSAGE.HOST_FULLSCREEN, v: PROTOCOL_VERSION, on});

/**
 * The host-stats message with the aggregated completion counts the app asked for.
 *
 * @param {Object} stats CourseStats: counts only, never who.
 * @returns {Object}
 */
export const hostStats = (stats) => ({type: MESSAGE.HOST_STATS, v: PROTOCOL_VERSION, stats});

/**
 * The host-stats message when there are no counts to give.
 *
 * @param {string} error One of STATS_ERRORS.
 * @returns {Object}
 */
export const hostStatsError = (error) => ({type: MESSAGE.HOST_STATS, v: PROTOCOL_VERSION, error});

/**
 * The host-overlay message: the host opened or closed an overlay above the app.
 *
 * @param {boolean} open
 * @returns {Object}
 */
export const hostOverlay = (open) => ({type: MESSAGE.HOST_OVERLAY, v: PROTOCOL_VERSION, open});

/**
 * The host-flow-progress message: the current user's own progress on a map.
 *
 * It is built field by field from what Moodle answered, so nothing else that comes back can reach the app.
 *
 * @param {string} mapId The map the app asked about.
 * @param {Object} reply What format_rumbos_get_flow_progress (or the write or the reset) returned.
 * @returns {?Object} Null when the reply is not well formed.
 */
export const hostFlowProgress = (mapId, reply) => {
    const threshold = reply?.config?.quizThreshold;
    if (!Array.isArray(reply?.items) || typeof reply.persistent !== 'boolean' ||
            !Number.isInteger(threshold) || threshold < 0 || threshold > 100) {
        return null;
    }
    const items = [];
    for (const item of reply.items) {
        if (!isStepKey(item?.stepKey) || !isRevision(item.revision) || !FLOW_METHODS.includes(item.method) ||
                typeof item.completedAt !== 'string') {
            return null;
        }
        items.push({stepKey: item.stepKey, revision: item.revision, method: item.method, completedAt: item.completedAt});
    }
    return {
        type: MESSAGE.HOST_FLOW_PROGRESS,
        v: PROTOCOL_VERSION,
        mapId,
        items,
        persistent: reply.persistent,
        config: {quizThreshold: threshold},
    };
};

/**
 * The host-flow-progress message when there is no progress to give.
 *
 * @param {string} mapId
 * @param {string} error One of FLOW_ERRORS.
 * @returns {Object}
 */
export const hostFlowProgressError = (mapId, error) => ({
    type: MESSAGE.HOST_FLOW_PROGRESS,
    v: PROTOCOL_VERSION,
    mapId,
    error: FLOW_ERRORS.includes(error) ? error : 'unavailable',
});

/**
 * Whether a value is a finite number or null.
 *
 * @param {*} value
 * @returns {boolean}
 */
const isNumberOrNull = (value) => value === null || (typeof value === 'number' && Number.isFinite(value));

/**
 * The host-quiz-result message: the current user's own result in a quiz.
 *
 * @param {number} cmid The quiz the app asked about.
 * @param {Object} result What format_rumbos_get_quiz_result returned.
 * @returns {?Object} Null when the result is not well formed.
 */
export const hostQuizResult = (cmid, result) => {
    const counts = [result?.attempts, result?.finishedAttempts];
    if (!counts.every((count) => Number.isSafeInteger(count) && count >= 0) ||
            typeof result.inProgress !== 'boolean' || typeof result.pendingGrading !== 'boolean' ||
            !isNumberOrNull(result.percent) || !(result.passedThreshold === null || typeof result.passedThreshold === 'boolean')) {
        return null;
    }
    return {
        type: MESSAGE.HOST_QUIZ_RESULT,
        v: PROTOCOL_VERSION,
        cmid,
        result: {
            attempts: result.attempts,
            finishedAttempts: result.finishedAttempts,
            inProgress: result.inProgress,
            percent: result.percent,
            pendingGrading: result.pendingGrading,
            passedThreshold: result.passedThreshold,
        },
    };
};

/**
 * The host-quiz-result message when there is no result to give.
 *
 * @param {number} cmid
 * @param {string} error One of QUIZ_ERRORS.
 * @returns {Object}
 */
export const hostQuizResultError = (cmid, error) => ({
    type: MESSAGE.HOST_QUIZ_RESULT,
    v: PROTOCOL_VERSION,
    cmid,
    error: QUIZ_ERRORS.includes(error) ? error : 'unavailable',
});

/**
 * Path of the Moodle site without a trailing slash ("" for a site at the root of its host).
 *
 * @param {URL} root The wwwroot URL.
 * @returns {string}
 */
const rootPath = (root) => root.pathname.replace(/\/+$/, '');

/**
 * Decides how to open an activity, using ONLY the host's own last state.
 *
 * The app never supplies URLs. The cmid must be in the state, the activity must
 * be openable (not restricted, with a URL) and the URL must be a Moodle URL:
 *  - "popup": same origin as this page and under {wwwroot}/mod/, and the module
 *    is not in the new-tab list.
 *  - "tab": any other URL under the Moodle site (a module that works poorly in a
 *    frame, or a page that is not an activity).
 *  - null: not a Moodle URL at all, so it is not opened.
 *
 * @param {?{activities: Array}} state Last CourseState received from Moodle.
 * @param {number} cmid Course module id requested by the app.
 * @param {{siteOrigin: string, wwwroot: string, newTabModules: string[]}} site Where the page is running.
 * @returns {?{target: string, url: string, title: string, modname: string}} What to open, or null when it must not be opened.
 */
export const resolveActivityTarget = (state, cmid, {siteOrigin, wwwroot, newTabModules}) => {
    const activity = state?.activities?.find((candidate) => candidate.cmid === cmid);
    if (!activity || activity.availability === 'restricted' || typeof activity.url !== 'string') {
        return null;
    }
    try {
        const root = new URL(wwwroot);
        const url = new URL(activity.url, siteOrigin);
        const base = rootPath(root);
        if (!['http:', 'https:'].includes(url.protocol) || url.origin !== root.origin ||
                (url.pathname !== base && !url.pathname.startsWith(`${base}/`))) {
            return null;
        }
        const inMod = url.origin === siteOrigin && url.pathname.startsWith(`${base}/mod/`);
        const popup = inMod && !newTabModules.includes(activity.modname);
        return {
            target: popup ? 'popup' : 'tab',
            url: url.href,
            title: String(activity.name ?? ''),
            modname: String(activity.modname ?? ''),
        };
    } catch (error) {
        return null;
    }
};

/**
 * Whether the host's last state lists an activity.
 *
 * It is the only thing the host needs to know about an activity before asking Moodle for its settings page:
 * unlike opening an activity, configuring it does not depend on the activity being available to the user.
 *
 * @param {?{activities: Array}} state Last CourseState received from Moodle.
 * @param {number} cmid Course module id requested by the app.
 * @returns {boolean}
 */
export const hasActivity = (state, cmid) => Array.isArray(state?.activities) &&
    state.activities.some((candidate) => candidate.cmid === cmid);

/**
 * Whether an address is the activity settings page of this Moodle site, the only kind the host opens for the editor.
 *
 * Moodle builds the address; this is a second check on what came back, so a wrong answer can never send
 * the editor to another site or another page.
 *
 * @param {string} href
 * @param {{wwwroot: string}} site
 * @returns {?string} The normalised address, or null when it must not be opened.
 */
export const resolveSettingsUrl = (href, {wwwroot}) => {
    try {
        const root = new URL(wwwroot);
        const url = new URL(href);
        const isSettingsPage = url.pathname === `${rootPath(root)}/course/modedit.php` &&
            /^[1-9]\d*$/.test(url.searchParams.get('update') ?? '');
        return ['http:', 'https:'].includes(url.protocol) && url.origin === root.origin && isSettingsPage ? url.href : null;
    } catch (error) {
        return null;
    }
};

/**
 * Whether a URL is the view page of a course (where "Continue" and "Back to course" lead).
 *
 * @param {string} href
 * @param {{wwwroot: string, courseId: number}} site
 * @returns {boolean}
 */
export const isCourseViewUrl = (href, {wwwroot, courseId}) => {
    try {
        const root = new URL(wwwroot);
        const url = new URL(href);
        return url.origin === root.origin &&
            url.pathname === `${rootPath(root)}/course/view.php` &&
            url.searchParams.get('id') === String(courseId);
    } catch (error) {
        return false;
    }
};

/**
 * Validates a message sent by the activity page inside the popup.
 *
 * @param {{origin: string, source: *, data: *}} event
 * @param {{siteOrigin: string, frameWindow: *}} expected The popup frame's own window on this site.
 * @returns {?string} The message type, or null when the event must be ignored.
 */
export const parsePopupMessage = (event, {siteOrigin, frameWindow}) => {
    if (!event || !frameWindow || event.origin !== siteOrigin || event.source !== frameWindow) {
        return null;
    }
    const data = event.data;
    if (!isPlainObject(data) || data.v !== PROTOCOL_VERSION || !Object.values(POPUP_MESSAGE).includes(data.type)) {
        return null;
    }
    return data.type;
};
